export const SmartphoneAsset: React.FC<AssetProps> = ({
  size = 'L',
  role = 'foreground',
  ...props
}) => {
  const isGhost = role === 'ghost';

  return (
    <AssetContainer size={size} role={role} {...props}>
      {/* Ground contact drop shadow (0-radius to prevent staining underlying objects) */}
      <ellipse
        cx="0"
        cy={50}
        rx={0}
        ry={0}
        fill="var(--token-secondary)"
        opacity={isGhost ? 0.15 : 0.8}
      />

      <g transform="scale(0.98717)">
        <g transform="translate(-300.61, -282.93)">
          {SMARTPHONE_PATHS.map((p, i) => (
            <path
              key={i}
              d={p.d}
              fill={getSmartphoneFill(p.role, isGhost)}
            />
          ))}
        </g>
      </g>
    </AssetContainer>
  );
};
